import nextVitals from 'eslint-config-next/core-web-vitals'
import nextTs from 'eslint-config-next/typescript'

// `eslint-config-next@16` ships native flat config, so it is spread directly — routing it through
// `FlatCompat` is what threw "Converting circular structure to JSON" here.
const eslintConfig = [
  // `public/sw.js` is the compiled service worker, generated by Serwist on every build. Linting it
  // reports the inside of a bundler's output, not our code.
  {
    ignores: [
      '.next/**',
      '.next-docs/**',
      'node_modules/**',
      'next-env.d.ts',
      'public/sw.js',
      'public/sw.js.map',
    ],
  },
  ...nextVitals,
  ...nextTs,
]

export default eslintConfig
